  },
  {
    id: 'p7',
    name: 'Turned Walnut Bowl',
    category: 'woodwork',
    price: 95,
    image: '/airo-assets/images/products/woodwork-bowl',
    featured: true,
    description: 'A beautifully turned walnut bowl showcasing the natural grain of the wood.',
