import { motion } from 'motion/react';
import { Link } from 'react-router-dom';
import type { Product } from '../server/api/products/GET';

interface ProductCardProps {
  product: Product;
  index?: number;
}

const categoryColors: Record<string, string> = {
  pottery: 'bg-orange-100 text-orange-800',
  textiles: 'bg-amber-100 text-amber-800',
  woodwork: 'bg-yellow-100 text-yellow-800',
  jewelry: 'bg-rose-100 text-rose-800',
};

export default function ProductCard({ product, index = 0 }: ProductCardProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.07, ease: 'easeOut' as const }}
      whileHover={{ y: -4 }}
      className="group bg-card rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-shadow duration-300 cursor-pointer"
    >
      <Link to={`/products`} aria-label={`View ${product.name}`}>
        <div className="aspect-square overflow-hidden bg-muted">
          <img
            src={product.image}
            alt={product.name}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            loading="lazy"
          />
        </div>
        <div className="p-4">
          <div className="flex items-start justify-between gap-2 mb-1">
            <h3 className="font-semibold text-foreground text-sm leading-snug line-clamp-2">
              {product.name}
            </h3>
            <span
              className={`shrink-0 text-xs font-medium px-2 py-0.5 rounded-full capitalize ${
                categoryColors[product.category] ?? 'bg-muted text-muted-foreground'
              }`}
            >
              {product.category}
            </span>
          </div>
          <p className="text-primary font-bold text-base mt-2">${product.price}</p>
        </div>
      </Link>
    </motion.div>
  );
}

import { useLoaderData, useSearchParams, Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { motion } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { SlidersHorizontal } from 'lucide-react';
import ProductCard from '../components/ProductCard';
import type { Product } from '../server/api/products/GET';

type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

const CATEGORIES: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

interface LoaderData {
  products: Product[];
  initialCategory: string;
}

export async function productsLoader({ request }: { request: Request }): Promise<LoaderData> {
  const url = new URL(request.url);
  const category = url.searchParams.get('category') ?? '';
  const apiUrl = category
    ? `/api/products?category=${encodeURIComponent(category)}`
    : '/api/products';
  const res = await fetch(apiUrl);
  const products: Product[] = await res.json();
  return { products, initialCategory: category };
}

function ProductSkeleton() {
  return (
    <div className="rounded-xl overflow-hidden bg-card animate-pulse">
      <div className="aspect-square bg-muted" />
      <div className="p-4 space-y-2">
        <div className="h-4 bg-muted rounded w-3/4" />
        <div className="h-3 bg-muted rounded w-1/2" />
        <div className="h-4 bg-muted rounded w-1/4 mt-2" />
      </div>
    </div>
  );
}

export default function ProductsPage() {
  const loaderData = useLoaderData() as LoaderData | null;
  const [searchParams, setSearchParams] = useSearchParams();
  const urlCategory = (searchParams.get('category') ?? 'all') as Category;

  const [activeCategory, setActiveCategory] = useState<Category>(
    (loaderData?.initialCategory as Category) || urlCategory || 'all'
  );
  const [products, setProducts] = useState<Product[]>(loaderData?.products ?? []);
  const [loading, setLoading] = useState(false);

  // Sync with URL param changes (e.g. from footer links)
  useEffect(() => {
    const cat = (searchParams.get('category') ?? 'all') as Category;
    if (cat !== activeCategory) {
      setActiveCategory(cat);
    }
  }, [searchParams]);

  // Fetch when category changes (client-side navigation)
  useEffect(() => {
    if (loaderData && activeCategory === ((loaderData.initialCategory || 'all') as Category)) {
      setProducts(loaderData.products);
      return;
    }
    setLoading(true);
    const url =
      activeCategory === 'all'
        ? '/api/products'
        : `/api/products?category=${activeCategory}`;
    fetch(url)
      .then((r) => r.json())
      .then((data: Product[]) => {
        setProducts(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [activeCategory]);

  const handleCategoryChange = (cat: Category) => {
    setActiveCategory(cat);
    if (cat === 'all') {
      setSearchParams({});
    } else {
      setSearchParams({ category: cat });
    }
  };

  const categoryLabel =
    CATEGORIES.find((c) => c.value === activeCategory)?.label ?? 'All';

  return (
    <>
      <Helmet>
        <title>
          {activeCategory === 'all'
            ? 'Shop All — Artisan Goods Co.'
            : `${categoryLabel} — Artisan Goods Co.`}
        </title>
        <meta
          name="description"
          content="Browse our full collection of handcrafted pottery, textiles, woodwork, and jewelry. Each piece made with care by skilled artisans."
        />
      </Helmet>

      {/* Page Header */}
      <section className="bg-muted py-16 border-b border-border/30">
        <div className="container mx-auto px-6">
          <motion.div
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, ease: 'easeOut' as const }}
          >
            <p className="text-primary text-sm font-medium tracking-widest uppercase mb-2">
              Our Collection
            </p>
            <h1
              className="text-4xl md:text-5xl font-bold text-foreground"
              style={{ fontFamily: 'var(--font-heading)' }}
            >
              {activeCategory === 'all' ? 'All Handcrafted Goods' : categoryLabel}
            </h1>
            <p className="text-muted-foreground mt-3 text-base max-w-xl">
              Every item is made by hand with natural materials and genuine care.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Filters + Grid */}
      <section className="py-12 container mx-auto px-6">
        {/* Filter pills */}
        <div className="flex items-center gap-3 mb-10 flex-wrap">
          <SlidersHorizontal size={16} className="text-muted-foreground shrink-0" />
          {CATEGORIES.map((cat) => (
            <button
              key={cat.value}
              onClick={() => handleCategoryChange(cat.value)}
              className={`px-5 py-2 rounded-full text-sm font-medium transition-all duration-200 ${
                activeCategory === cat.value
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'bg-muted text-foreground/70 hover:bg-muted/80 hover:text-foreground'
              }`}
            >
              {cat.label}
            </button>
          ))}
          <span className="ml-auto text-sm text-muted-foreground">
            {products.length} {products.length === 1 ? 'item' : 'items'}
          </span>
        </div>

        {/* Product Grid */}
        {loading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {Array.from({ length: 6 }).map((_, i) => (
              <ProductSkeleton key={i} />
            ))}
          </div>
        ) : products.length === 0 ? (
          <div className="text-center py-24">
            <p className="text-muted-foreground text-lg">No products found in this category.</p>
            <button
              onClick={() => handleCategoryChange('all')}
              className="mt-4 text-primary text-sm font-medium hover:underline"
            >
              View all products
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {products.map((product, i) => (
              <ProductCard key={product.id} product={product} index={i} />
            ))}
          </div>
        )}
      </section>

      {/* Bottom CTA */}
      <section className="py-16 bg-muted border-t border-border/30">
        <div className="container mx-auto px-6 text-center">
          <p className="text-muted-foreground text-sm mb-2">Looking for something special?</p>
          <h2
            className="text-2xl font-bold text-foreground mb-4"
            style={{ fontFamily: 'var(--font-heading)' }}
          >
            Custom Orders Welcome
          </h2>
          <p className="text-muted-foreground text-sm max-w-md mx-auto mb-6">
            Our artisans love creating bespoke pieces. Reach out and let's make something
            together.
          </p>
          <Link
            to="/about"
            className="inline-flex items-center gap-2 px-6 py-3 bg-primary text-primary-foreground font-medium rounded-full hover:opacity-90 transition-opacity text-sm"
          >
            Meet the Makers
          </Link>
        </div>
      </section>
    </>
  );
}

